// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("delivers to the topic's subscribers in subscription order", () -> {
        var bus = new EventBus();
        var log = new ArrayList<String>();
        bus.subscribe("orders.created", m -> log.add("billing " + m));
        bus.subscribe("orders.created", m -> log.add("email " + m));
        eq(bus.publish("orders.created", "#17"), 2);
        eq(log, List.of("billing #17", "email #17"));
    });
    test("exact topics match only themselves", () -> {
        var bus = new EventBus();
        var log = new ArrayList<String>();
        bus.subscribe("orders", log::add);
        eq(bus.publish("orders.created", "a"), 0);
        eq(bus.publish("payments", "b"), 0);
        eq(bus.publish("orders", "c"), 1);
        eq(log, List.of("c"));
    });
    test("a wildcard matches deeper topics but not the bare prefix", () -> {
        var bus = new EventBus();
        var log = new ArrayList<String>();
        bus.subscribe("orders.*", log::add);
        bus.publish("orders.created", "1");
        bus.publish("orders.eu.created", "2");
        bus.publish("orders", "3");
        bus.publish("ordersx.created", "4");
        eq(log, List.of("1", "2"));
    });
    test("a failing subscriber does not stop the others", () -> {
        var bus = new EventBus();
        var log = new ArrayList<String>();
        bus.subscribe("t", m -> log.add("first"));
        bus.subscribe("t", m -> { throw new IllegalStateException("broken"); });
        bus.subscribe("t", m -> log.add("third"));
        eq(bus.publish("t", "x"), 2);
        eq(log, List.of("first", "third"));
        eq(bus.failures(), 1);
    });
    test("unsubscribing stops delivery and is safe to repeat", () -> {
        var bus = new EventBus();
        var log = new ArrayList<String>();
        var stop = bus.subscribe("t", m -> log.add("a " + m));
        bus.subscribe("t", m -> log.add("b " + m));
        bus.publish("t", "1");
        stop.run();
        stop.run();
        bus.publish("t", "2");
        eq(log, List.of("a 1", "b 1", "b 2"));
    });
    test("the same handler subscribed twice gets every message twice", () -> {
        var bus = new EventBus();
        var log = new ArrayList<String>();
        Consumer<String> handler = log::add;
        bus.subscribe("t", handler);
        bus.subscribe("t", handler);
        eq(bus.publish("t", "x"), 2);
        eq(log, List.of("x", "x"));
    });
    test("unsubscribe removes exactly its own subscription", () -> {
        var bus = new EventBus();
        var log = new ArrayList<String>();
        Consumer<String> handler = log::add;
        bus.subscribe("t", handler);
        var second = bus.subscribe("t.*", handler);
        second.run();
        bus.publish("t", "kept");
        bus.publish("t.sub", "gone");
        eq(log, List.of("kept"));
    });
    test("publishing with no subscribers delivers nothing", () -> {
        var bus = new EventBus();
        eq(bus.publish("nobody.listens", "x"), 0);
        eq(bus.failures(), 0);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("hands messages out in arrival order", () -> {
        var q = new BoundedQueue(3, Policy.REJECT);
        eq(q.offer("a"), true);
        eq(q.offer("b"), true);
        eq(q.poll(), Optional.of("a"));
        eq(q.poll(), Optional.of("b"));
        eq(q.poll(), Optional.empty());
    });
    test("REJECT refuses when full and keeps what it has", () -> {
        var q = full(Policy.REJECT);
        eq(q.offer("c"), false);
        eq(q.rejected(), 1);
        eq(q.dropped(), 0);
        eq(q.pollBatch(5), List.of("a", "b"));
    });
    test("REJECT accepts again once there is room", () -> {
        var q = full(Policy.REJECT);
        q.offer("c");
        q.poll();
        eq(q.offer("c"), true);
        eq(q.pollBatch(5), List.of("b", "c"));
    });
    test("DROP_OLDEST throws away the head to make room", () -> {
        var q = full(Policy.DROP_OLDEST);
        eq(q.offer("c"), true);
        eq(q.offer("d"), true);
        eq(q.dropped(), 2);
        eq(q.rejected(), 0);
        eq(q.pollBatch(5), List.of("c", "d"));
    });
    test("DROP_NEWEST throws away the incoming message", () -> {
        var q = full(Policy.DROP_NEWEST);
        eq(q.offer("c"), false);
        eq(q.dropped(), 1);
        eq(q.rejected(), 0);
        eq(q.pollBatch(5), List.of("a", "b"));
    });
    test("pollBatch takes at most max, oldest first", () -> {
        var q = new BoundedQueue(5, Policy.REJECT);
        for (var m : List.of("a", "b", "c")) q.offer(m);
        eq(q.pollBatch(2), List.of("a", "b"));
        eq(q.size(), 1);
        eq(q.pollBatch(2), List.of("c"));
        eq(q.pollBatch(2), List.of());
        raises(IllegalArgumentException.class, () -> q.pollBatch(0));
    });
    test("the high-water mark is the peak size, never above capacity", () -> {
        var q = full(Policy.DROP_OLDEST);
        q.offer("c");
        q.pollBatch(2);
        q.offer("d");
        eq(q.highWater(), 2);
        eq(q.size(), 1);
        var roomy = new BoundedQueue(5, Policy.REJECT);
        for (var m : List.of("a", "b", "c")) roomy.offer(m);
        eq(roomy.highWater(), 3);
    });
    test("refuses a capacity below one", () -> {
        raises(IllegalArgumentException.class, () -> new BoundedQueue(0, Policy.REJECT));
        eq(new BoundedQueue(1, Policy.DROP_NEWEST).offer("x"), true);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

