public static void main(String[] args) {
    test("an order and its event are written together", () -> {
        var s = new OrderService();
        s.placeOrder("o1", 500);
        eq(s.orders(), Map.of("o1", 500L));
        eq(s.pending(), List.of("OrderPlaced o1 500"));
    });
    test("a rejected order writes neither the order nor the event", () -> {
        var s = withOrders("o1");
        raises(IllegalArgumentException.class, () -> s.placeOrder("o1", 900));
        raises(IllegalArgumentException.class, () -> s.placeOrder("o2", 0));
        eq(s.orders(), Map.of("o1", 100L));
        eq(s.pending(), List.of("OrderPlaced o1 100"));
    });
    test("relay publishes pending events in order, then marks them", () -> {
        var s = withOrders("o1", "o2");
        var sent = new ArrayList<String>();
        Consumer<String> broker = e -> {
            ok(s.pending().contains(e), e + " was marked published before it was sent");
            sent.add(e);
        };
        eq(s.relay(broker, 10), 2);
        eq(sent, List.of("OrderPlaced o1 100", "OrderPlaced o2 100"));
        eq(s.pending(), List.of());
    });
    test("relay sends at most batchSize events per call", () -> {
        var s = withOrders("o1", "o2", "o3");
        var sent = new ArrayList<String>();
        eq(s.relay(sent::add, 2), 2);
        eq(s.pending(), List.of("OrderPlaced o3 100"));
        eq(s.relay(sent::add, 2), 1);
        eq(sent.size(), 3);
    });
    test("a failed publish stops the batch and stays pending", () -> {
        var s = withOrders("o1", "o2", "o3");
        var sent = new ArrayList<String>();
        Consumer<String> flaky = e -> {
            if (e.contains("o2")) throw new IllegalStateException("broker down");
            sent.add(e);
        };
        eq(s.relay(flaky, 10), 1);
        eq(sent, List.of("OrderPlaced o1 100"));
        eq(s.pending(), List.of("OrderPlaced o2 100", "OrderPlaced o3 100"));
    });
    test("the next relay retries from the failed event, in order", () -> {
        var s = withOrders("o1", "o2", "o3");
        s.relay(e -> { if (e.contains("o2")) throw new IllegalStateException("down"); }, 10);
        var sent = new ArrayList<String>();
        eq(s.relay(sent::add, 10), 2);
        eq(sent, List.of("OrderPlaced o2 100", "OrderPlaced o3 100"));
    });
    test("published events are never sent again", () -> {
        var s = withOrders("o1");
        s.relay(e -> {}, 10);
        var sent = new ArrayList<String>();
        eq(s.relay(sent::add, 10), 0);
        eq(sent, List.of());
    });
    test("purge deletes only published rows", () -> {
        var s = withOrders("o1", "o2", "o3");
        s.relay(e -> {}, 2);
        eq(s.purgePublished(), 2);
        eq(s.purgePublished(), 0);
        eq(s.pending(), List.of("OrderPlaced o3 100"));
        var sent = new ArrayList<String>();
        s.relay(sent::add, 10);
        eq(sent, List.of("OrderPlaced o3 100"));
    });
    test("refuses a batch size below one", () ->
        raises(IllegalArgumentException.class, () -> withOrders("o1").relay(e -> {}, 0)));
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("a task runs at its time, not before", () -> {
        var now = new long[] {0};
        var s = new Scheduler(() -> now[0]);
        s.schedule("a", 0, 50);
        now[0] = 49;
        eq(s.runDue(), List.of());
        now[0] = 50;
        eq(s.runDue(), List.of("a"));
        eq(s.runDue(), List.of());
    });
    test("due tasks run highest priority first", () -> {
        var now = new long[] {0};
        var s = new Scheduler(() -> now[0]);
        s.schedule("low", 1, 10);
        s.schedule("high", 9, 30);
        s.schedule("mid", 5, 20);
        now[0] = 100;
        eq(s.runDue(), List.of("high", "mid", "low"));
    });
    test("equal priority runs by time, then first come first served", () -> {
        var now = new long[] {0};
        var s = new Scheduler(() -> now[0]);
        s.schedule("late", 1, 40);
        s.schedule("zed", 1, 10);
        s.schedule("amy", 1, 10);
        now[0] = 100;
        eq(s.runDue(), List.of("zed", "amy", "late"));
    });
    test("cancel removes a pending task", () -> {
        var now = new long[] {0};
        var s = new Scheduler(() -> now[0]);
        s.schedule("a", 0, 10);
        s.schedule("b", 0, 10);
        eq(s.cancel("a"), true);
        eq(s.cancel("a"), false);
        eq(s.cancel("nope"), false);
        now[0] = 10;
        eq(s.runDue(), List.of("b"));
        eq(s.cancel("b"), false);
    });
    test("a recurring task runs once per period", () -> {
        var now = new long[] {0};
        var s = new Scheduler(() -> now[0]);
        s.every("tick", 0, 100);
        eq(s.nextRunAt(), Optional.of(100L));
        now[0] = 100;
        eq(s.runDue(), List.of("tick"));
        now[0] = 150;
        eq(s.runDue(), List.of());
        now[0] = 200;
        eq(s.runDue(), List.of("tick"));
        eq(s.nextRunAt(), Optional.of(300L));
    });
    test("a late recurring task runs once and keeps its rate", () -> {
        var now = new long[] {0};
        var s = new Scheduler(() -> now[0]);
        s.every("tick", 0, 100);
        now[0] = 450;
        eq(s.runDue(), List.of("tick"));
        eq(s.nextRunAt(), Optional.of(500L));
        now[0] = 500;
        eq(s.runDue(), List.of("tick"));
        now[0] = 700;
        eq(s.runDue(), List.of("tick"));
        eq(s.nextRunAt(), Optional.of(800L));
    });
    test("a mix of one-off and recurring tasks", () -> {
        var now = new long[] {0};
        var s = new Scheduler(() -> now[0]);
        s.schedule("a", 1, 50);
        s.every("tick", 0, 100);
        now[0] = 100;
        eq(s.runDue(), List.of("a", "tick"));
        eq(s.nextRunAt(), Optional.of(200L));
        s.cancel("tick");
        eq(s.nextRunAt(), Optional.empty());
        now[0] = 0;
        var t = new Scheduler(() -> now[0]);
        t.every("tick", 0, 100);
        now[0] = 50;
        t.schedule("b", 0, 150);
        now[0] = 100;
        eq(t.runDue(), List.of("tick"));
        now[0] = 200;
        eq(t.runDue(), List.of("tick", "b"));
    });
    test("refuses negative delays, empty periods and duplicate names", () -> {
        var s = new Scheduler(() -> 0);
        raises(IllegalArgumentException.class, () -> s.schedule("a", 0, -1));
        raises(IllegalArgumentException.class, () -> s.every("b", 0, 0));
        s.schedule("a", 0, 0);
        raises(IllegalArgumentException.class, () -> s.schedule("a", 0, 5));
        raises(IllegalArgumentException.class, () -> s.every("a", 0, 5));
    });
    test("a finished task's name can be scheduled again", () -> {
        var now = new long[] {0};
        var s = new Scheduler(() -> now[0]);
        s.schedule("a", 0, 0);
        eq(s.runDue(), List.of("a"));
        s.schedule("a", 0, 5);
        now[0] = 5;
        eq(s.runDue(), List.of("a"));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("replay folds a stream into the current state", () -> {
        eq(replay(List.of(new Opened("ada"), new Deposited(500), new Withdrawn(200))),
           new Account("ada", 300, 3));
        eq(replay(List.of(new Opened("bob"))), new Account("bob", 0, 1));
    });
    test("replaying a prefix shows the past", () -> {
        var events = bank().events("acc-1");
        eq(events.size(), 3);
        eq(replay(events.subList(0, 2)), new Account("ada", 500, 2));
        eq(replay(events), new Account("ada", 300, 3));
    });
    test("refuses streams that are empty or do not start with Opened", () -> {
        raises(IllegalStateException.class, () -> replay(List.of()));
        raises(IllegalStateException.class, () -> replay(List.of(new Deposited(5))));
        raises(IllegalStateException.class, () -> replay(List.of(new Opened("a"), new Opened("b"))));
    });
    test("append checks the expected version", () -> {
        var s = new EventStore();
        eq(s.append("x", 0, List.of(new Opened("ada"), new Deposited(5))), 2);
        raises(IllegalStateException.class, () -> s.append("x", 1, List.of(new Deposited(7))));
        eq(s.events("x"), List.of(new Opened("ada"), new Deposited(5)));
        eq(s.append("x", 2, List.of(new Deposited(7))), 3);
        eq(s.events("unknown"), List.of());
    });
    test("of two writers that read the same version, the second loses", () -> {
        var s = bank();
        int seen = replay(s.events("acc-1")).version();
        s.append("acc-1", seen, List.of(new Withdrawn(300)));
        raises(IllegalStateException.class, () -> s.append("acc-1", seen, List.of(new Withdrawn(300))));
        eq(replay(s.events("acc-1")).balance(), 0);
    });
    test("commands validate against replayed state and append one event", () -> {
        var s = bank();
        raises(IllegalStateException.class, () -> withdraw(s, "acc-1", 301));
        raises(IllegalArgumentException.class, () -> deposit(s, "acc-1", 0));
        raises(IllegalStateException.class, () -> deposit(s, "nope", 10));
        raises(IllegalStateException.class, () -> open(s, "acc-1", "eve"));
        eq(s.events("acc-1").size(), 3);
        withdraw(s, "acc-1", 300);
        eq(s.events("acc-1").get(3), new Withdrawn(300));
    });
    test("the global log records every event in append order", () -> {
        var s = bank();
        open(s, "acc-2", "bob");
        eq(s.log(), List.of(
            new Recorded("acc-1", 1, new Opened("ada")),
            new Recorded("acc-1", 2, new Deposited(500)),
            new Recorded("acc-1", 3, new Withdrawn(200)),
            new Recorded("acc-2", 1, new Opened("bob"))));
    });
    test("a projection totals balances per owner from the log", () -> {
        var s = bank();
        open(s, "acc-2", "bob");
        open(s, "acc-3", "ada");
        deposit(s, "acc-3", 50);
        deposit(s, "acc-2", 70);
        eq(balanceByOwner(s.log()), Map.of("ada", 350L, "bob", 70L));
        eq(balanceByOwner(s.log().subList(0, 2)), Map.of("ada", 500L));
    });
    test("streams are read-only to callers", () -> {
        var s = bank();
        raises(UnsupportedOperationException.class, () -> s.events("acc-1").add(new Deposited(1)));
        eq(replay(s.events("acc-1")).balance(), 300);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("all steps succeed: COMPLETED and nothing undone", () -> {
        var booked = new HashSet<String>();
        var r = run(List.of(book(booked, "flight"), book(booked, "hotel")), 1);
        eq(r.status(), Status.COMPLETED);
        eq(r.log(), List.of("do flight", "do hotel"));
        eq(booked, Set.of("flight", "hotel"));
    });
    test("a failure undoes the succeeded steps, newest first", () -> {
        var booked = new HashSet<String>();
        var r = run(List.of(book(booked, "flight"), book(booked, "hotel"), broken("car", "sold out")), 1);
        eq(r.status(), Status.COMPENSATED);
        eq(r.log(), List.of("do flight", "do hotel", "fail car: sold out", "undo hotel", "undo flight"));
        eq(booked, Set.of());
    });
    test("steps after the failure never run", () -> {
        var booked = new HashSet<String>();
        var r = run(List.of(book(booked, "flight"), broken("hotel", "full"), book(booked, "car")), 1);
        eq(r.log(), List.of("do flight", "fail hotel: full", "undo flight"));
        eq(booked, Set.of());
    });
    test("a failing first step has nothing to undo", () -> {
        var r = run(List.of(broken("flight", "no seats"), book(new HashSet<>(), "hotel")), 3);
        eq(r.status(), Status.COMPENSATED);
        eq(r.log(), List.of("fail flight: no seats"));
    });
    test("a flaky compensation is retried until it works", () -> {
        var booked = new HashSet<String>();
        var hotel = new Step("hotel", () -> booked.add("hotel"), flaky(2, () -> booked.remove("hotel")));
        var r = run(List.of(hotel, broken("car", "sold out")), 3);
        eq(r.status(), Status.COMPENSATED);
        eq(r.log(), List.of("do hotel", "fail car: sold out",
                            "undo hotel failed: timeout", "undo hotel failed: timeout", "undo hotel"));
        eq(booked, Set.of());
    });
    test("a compensation out of attempts leaves the saga STUCK", () -> {
        var booked = new HashSet<String>();
        var hotel = new Step("hotel", () -> booked.add("hotel"), flaky(5, () -> booked.remove("hotel")));
        var r = run(List.of(book(booked, "flight"), hotel, broken("car", "sold out")), 2);
        eq(r.status(), Status.STUCK);
        eq(r.log(), List.of("do flight", "do hotel", "fail car: sold out",
                            "undo hotel failed: timeout", "undo hotel failed: timeout", "undo flight"));
        eq(booked, Set.of("hotel"));
    });
    test("an empty saga completes", () -> {
        var r = run(List.of(), 1);
        eq(r.status(), Status.COMPLETED);
        eq(r.log(), List.of());
    });
    test("refuses fewer than one compensation attempt", () ->
        raises(IllegalArgumentException.class, () -> run(List.of(), 0)));
    System.exit(report());
}
