        test("equal priority runs by time, then first come first served", () -> {
            var now = new long[] {0};
            var s = new Scheduler(() -> now[0]);
            s.schedule("late", 1, 40);
            s.schedule("zed", 1, 10);
            s.schedule("amy", 1, 10);
            now[0] = 100;
            eq(s.runDue(), List.of("zed", "amy", "late"));
